head.script:
scwin.tr_onclick = function(e) {
    for (var i = 0; i < 2; i++) {
        floating.show();
    }
};
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#floating').css('display') == 'block';
};
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#floating').css('z-index') == '4500';
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tr').click()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
